import{_ as n,o as r,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"RBD in Squid and Beyond - Ramana Krisna Venkatesh Raja, IBM Canada Ltd & Prasanna Kumar Kalever, IBM","description":"","frontmatter":{"title":"RBD in Squid and Beyond - Ramana Krisna Venkatesh Raja, IBM Canada Ltd & Prasanna Kumar Kalever, IBM","date":"2025-01-26T00:00:00.000Z","updated":"2025-01-26T00:00:00.000Z","tags":["Ceph","RBD","Storage Optimization","Distributed Storage","Data Replication"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/RBD_in_Squid_and_Beyond_-_Ramana_Krisna_Venkatesh_Raja_IBM_Canada_Ltd_Prasanna_Kumar_Kalever_IBM.md","filePath":"posts/2025/RBD_in_Squid_and_Beyond_-_Ramana_Krisna_Venkatesh_Raja_IBM_Canada_Ltd_Prasanna_Kumar_Kalever_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2025/RBD_in_Squid_and_Beyond_-_Ramana_Krisna_Venkatesh_Raja_IBM_Canada_Ltd_Prasanna_Kumar_Kalever_IBM.md"};function o(e,a,s,_,d,u){return r(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要-ceph-rbd-功能更新与未来计划" tabindex="-1">会议纪要：Ceph RBD 功能更新与未来计划 <a class="header-anchor" href="#会议纪要-ceph-rbd-功能更新与未来计划" aria-label="Permalink to &quot;会议纪要：Ceph RBD 功能更新与未来计划&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph RBD 功能更新与未来计划</p><p><strong>会议时间</strong>: 未知</p><p><strong>会议地点</strong>: 线上会议</p><p><strong>主持人</strong>: Ramana Krisna Venkatesh Raja (IBM 软件工程师) 和 Prasanna Kumar Kalever (IBM 软件架构师)</p><p><strong>参会人员</strong>: Ceph RBD 开发团队成员及相关技术人员</p><h3 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h3><h4 id="_1-squid-版本中的-rbd-更新" tabindex="-1">1. <strong>Squid 版本中的 RBD 更新</strong> <a class="header-anchor" href="#_1-squid-版本中的-rbd-更新" aria-label="Permalink to &quot;1. **Squid 版本中的 RBD 更新**&quot;">​</a></h4><ul><li><strong>性能优化</strong>: 针对 QEMU RBD 驱动备份场景进行了性能优化，特别是在处理大 RBD 镜像时，显著提升了备份速度。</li><li><strong>RBD 镜像同步 (Mirroring)</strong>: <ul><li><strong>快照同步</strong>: 修复了在 IO 负载下进行镜像快照时可能导致次要镜像损坏的问题。</li><li><strong>快照调度器</strong>: 修复了在 Kubernetes 等受限环境中，快照调度器被阻止的问题。</li><li><strong>OSD 请求延迟</strong>: 通过优化 BlueStore 的快照修剪操作，降低了 OSD 请求的延迟。</li></ul></li><li><strong>组快照 (Group Snapshot)</strong>: 改进了组快照的可用性，允许从单个成员快照中手动创建 RBD 组克隆。</li></ul><h4 id="_2-未来计划与正在进行的工作" tabindex="-1">2. <strong>未来计划与正在进行的工作</strong> <a class="header-anchor" href="#_2-未来计划与正在进行的工作" aria-label="Permalink to &quot;2. **未来计划与正在进行的工作**&quot;">​</a></h4><ul><li><strong>实时迁移 (Live Migration)</strong>: <ul><li>支持跨 Ceph 集群的实时迁移，适用于计划迁移和负载均衡场景。</li><li>支持从加密镜像导入，但目前尚未解决导入时保留稀疏性的问题。</li><li>引入从 NBD 导出实时导入的功能，支持更多源格式。</li></ul></li><li><strong>快照同步增强</strong>: <ul><li>支持从命名空间到不同命名空间的镜像同步，为多租户灾难恢复场景提供支持。</li></ul></li><li><strong>性能优化</strong>: <ul><li>计划利用 PG upmap 读取均衡器和多步重试 CRUSH 规则来进一步提升性能。</li><li>改进擦除编码池 (Erasure Coded Pools) 的随机读取性能，特别是针对小块随机访问的优化。</li></ul></li><li><strong>NVMe-oF 支持</strong>: <ul><li>计划增强 RBD 对 NVMe over Fabric 协议的支持，提升高吞吐量和低延迟的性能。</li></ul></li><li><strong>灾难恢复功能</strong>: <ul><li>正在开发支持克隆镜像的快照同步功能，并计划在 Tentacle 版本中引入一致性组快照同步功能，适用于多镜像应用的灾难恢复。</li></ul></li></ul><h4 id="_3-一致性组快照同步-consistency-group-snapshot-mirroring" tabindex="-1">3. <strong>一致性组快照同步 (Consistency Group Snapshot Mirroring)</strong> <a class="header-anchor" href="#_3-一致性组快照同步-consistency-group-snapshot-mirroring" aria-label="Permalink to &quot;3. **一致性组快照同步 (Consistency Group Snapshot Mirroring)**&quot;">​</a></h4><ul><li><strong>背景</strong>: 现代应用通常依赖多个 RBD 镜像，传统的单镜像同步无法满足需求，因此需要一致性组快照同步。</li><li><strong>功能</strong>: <ul><li>支持对多个 RBD 镜像进行一致性快照，并确保这些快照在灾难恢复时能够同步到次要集群。</li><li>提供了一系列命令和 API，支持启用/禁用组同步、添加/移除镜像、手动或自动创建组快照、以及在灾难场景下的故障转移和恢复操作。</li></ul></li><li><strong>演示</strong>: 展示了如何在主集群和次集群之间进行组同步、故障转移和恢复操作，确保数据一致性。</li></ul><h4 id="_4-未来工作" tabindex="-1">4. <strong>未来工作</strong> <a class="header-anchor" href="#_4-未来工作" aria-label="Permalink to &quot;4. **未来工作**&quot;">​</a></h4><ul><li><strong>快照同步的负载均衡</strong>: 计划测试多个 RBD 镜像同步守护进程的负载均衡能力，并引入同步公平性机制，避免某些镜像被遗漏。</li><li><strong>快照校验</strong>: 计划改进快照同步的校验机制，避免简单地对次要镜像进行校验和比较。</li><li><strong>读缓存优化</strong>: 计划改进 libRBD 的读缓存机制，提升整体性能。</li></ul><h3 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划 <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划&quot;">​</a></h3><ol><li><p><strong>性能优化</strong>:</p><ul><li>继续推进 PG upmap 读取均衡器和多步重试 CRUSH 规则的优化，确保在 Tentacle 版本中引入。</li><li>改进擦除编码池的随机读取性能，特别是针对小块随机访问的优化。</li></ul></li><li><p><strong>NVMe-oF 支持</strong>:</p><ul><li>继续推进 NVMe over Fabric 协议的支持，确保在 Tentacle 版本中实现高可用性配置。</li></ul></li><li><p><strong>灾难恢复功能</strong>:</p><ul><li>完成一致性组快照同步功能的开发，并在 Tentacle 版本中发布。</li><li>继续改进快照同步的负载均衡和校验机制。</li></ul></li><li><p><strong>读缓存优化</strong>:</p><ul><li>调查并改进 libRBD 的读缓存机制，提升整体性能。</li></ul></li></ol><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><p><strong>会议结束时间</strong>: 未知</p><p><strong>下次会议计划</strong>: 未提及</p>',20)])])}const h=n(l,[["render",o]]);export{p as __pageData,h as default};
